using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;using Microsoft.Web.WebView2.Core;
sealed class SoundShelfHost {
 readonly CoreWebView2 core;readonly string folder;readonly JavaScriptSerializer json=new JavaScriptSerializer{MaxJsonLength=44000000,RecursionLimit=100};
 internal SoundShelfHost(CoreWebView2 browser){core=browser;folder=Path.Combine(JagoSuiteBootstrap.Root,"Sound","Tracks");core.WebMessageReceived+=Message;}
 string Target(string id){Guid value;if(!Guid.TryParseExact(id,"D",out value))throw new Exception("Invalid track identity.");return Path.Combine(folder,value.ToString("D")+".json");}
 void Message(object sender,CoreWebView2WebMessageReceivedEventArgs e){if(!e.Source.StartsWith("https://jagomusic.example/",StringComparison.OrdinalIgnoreCase))return;string request=null;try{var m=json.Deserialize<Dictionary<string,object>>(e.WebMessageAsJson);if(!m.ContainsKey("type")||Convert.ToString(m["type"])!="jago-sound-shelf")return;request=Convert.ToString(m["request"]);Directory.CreateDirectory(folder);string op=Convert.ToString(m["operation"]);object result=null;if(op=="list"){var items=new List<object>();foreach(string file in Directory.GetFiles(folder,"*.json")){try{var record=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(file));items.Add(new{id=record["id"],name=record["name"],folder=record["folder"],modified=record["modified"]});}catch{}}result=items;}else {string file=Target(Convert.ToString(m["id"]));if(op=="load"){if(!File.Exists(file))throw new Exception("That track is no longer on the shelf.");result=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(file));}else if(op=="save"){var record=m["record"] as Dictionary<string,object>;var doc=record["document"] as Dictionary<string,object>;if(doc==null||!doc.ContainsKey("format")||Convert.ToString(doc["format"])!="jagomusic")throw new Exception("Save a Jago Sound project.");string name=Convert.ToString(record["name"]),path=Convert.ToString(record["folder"]);if(name.Length>80||path.Length>160)throw new Exception("Use a shorter track or folder name.");if(!File.Exists(file)&&Directory.GetFiles(folder,"*.json").Length>=100)throw new Exception("The track shelf holds 100 projects. Export a backup before removing a track.");record["id"]=Path.GetFileNameWithoutExtension(file);record["modified"]=DateTime.UtcNow.ToString("o");string text=json.Serialize(record);if(text.Length>40000000)throw new Exception("Save this large track as a project file instead.");long total=Directory.GetFiles(folder,"*.json").Where(f=>f!=file).Sum(f=>new FileInfo(f).Length);if(total+System.Text.Encoding.UTF8.GetByteCount(text)>512000000)throw new Exception("The track shelf has reached its storage budget. Export backups before removing older tracks.");string temporary=file+".tmp";File.WriteAllText(temporary,text);if(File.Exists(file))File.Replace(temporary,file,null);else File.Move(temporary,file);result=new{id=record["id"],modified=record["modified"]};}else if(op=="remove"){File.Delete(file);result=true;}else throw new Exception("Unknown shelf action.");}core.PostWebMessageAsJson(json.Serialize(new{type="jago-sound-shelf-result",request=request,ok=true,result=result}));}catch(Exception error){if(request!=null)core.PostWebMessageAsJson(json.Serialize(new{type="jago-sound-shelf-result",request=request,ok=false,error=error.Message}));}}
}
